package blockquotes

import (
	"bytes"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"sync"

	"github.com/gohugoio/hugo/common/herrors"
	htext "github.com/gohugoio/hugo/common/text"
	"github.com/gohugoio/hugo/common/types/hstring"
	"github.com/gohugoio/hugo/markup/converter/hooks"
	"github.com/gohugoio/hugo/markup/goldmark/internal/render"
	"github.com/gohugoio/hugo/markup/internal/attributes"
	"github.com/yuin/goldmark"
	"github.com/yuin/goldmark/ast"
	"github.com/yuin/goldmark/renderer"
	"github.com/yuin/goldmark/renderer/html"
	"github.com/yuin/goldmark/util"
)

type (
	blockquotesExtension struct{}
	htmlRenderer         struct{}
)

func New() goldmark.Extender {
	return &blockquotesExtension{}
}

func (e *blockquotesExtension) Extend(m goldmark.Markdown) {
	m.Renderer().AddOptions(renderer.WithNodeRenderers(
		util.Prioritized(newHTMLRenderer(), 100),
	))
}

func newHTMLRenderer() renderer.NodeRenderer {
	r := &htmlRenderer{}
	return r
}

func (r *htmlRenderer) RegisterFuncs(reg renderer.NodeRendererFuncRegisterer) {
	reg.Register(ast.KindBlockquote, r.renderBlockquote)
}

const (
	typeRegular = "regular"
	typeAlert   = "alert"
)

func (r *htmlRenderer) renderBlockquote(w util.BufWriter, src []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	ctx := w.(*render.Context)
	n := node.(*ast.Blockquote)

	if entering {
		bufLen := ctx.Buffer.Len()
		ctx.PushPos(bufLen)
		return ast.WalkContinue, nil
	}

	pos := ctx.PopPos()
	bufBytes := ctx.Buffer.Bytes()
	captured := bufBytes[pos:]
	ctx.Buffer.Truncate(pos)
	kind := ast.KindBlockquote
	ordinal := ctx.GetAndIncrementOrdinal(kind)
	texts := string(captured)
	textLen := len(texts)
	typ := typeRegular
	alertType := ""
	renderCtx := ctx.RenderContext()
	docCtx := ctx.DocumentContext()

	if textLen > 0 {
		m := gitHubAlertRe.FindStringSubmatch(texts)
		if len(m) == 2 {
			rawAlert := m[1]
			if rawAlert != "" {
				normalized := strings.ToLower(rawAlert)
				switch normalized {
				case "note":
					alertType = "note"
				case "tip":
					alertType = "tip"
				case "warning":
					alertType = "warning"
				case "important":
					alertType = "important"
				case "caution":
					alertType = "caution"
				}
				if alertType != "" {
					typ = typeAlert
				}
			}
		}
	}

	renderer := renderCtx.GetRenderer(hooks.BlockquoteRendererType, typ)
	if renderer == nil {
		if n.Attributes() != nil {
			openTag := "<blockquote"
			_, _ = w.WriteString(openTag)
			for _, attr := range n.Attributes() {
				name := attr.Name
				allowed := false
				filter := html.BlockquoteAttributeFilter
				if filter != nil {
					if filter.Contains(name) {
						allowed = true
					} else if bytes.HasPrefix(name, []byte("data-")) {
						allowed = true
					}
				} else {
					allowed = true
				}
				if !allowed {
					continue
				}
				_, _ = w.WriteString(" ")
				_, _ = w.Write(name)
				_, _ = w.WriteString(`="`)
				var value []byte
				switch typed := attr.Value.(type) {
				case []byte:
					value = typed
				case string:
					value = []byte(typed)
				}
				_, _ = w.Write(util.EscapeHTML(value))
				_ = w.WriteByte('"')
			}
			_ = w.WriteByte('>')
		} else {
			_, _ = w.WriteString("<blockquote>\n")
		}
		_, _ = w.WriteString(texts)
		closeTag := "</blockquote>\n"
		_, _ = w.WriteString(closeTag)
		return ast.WalkContinue, nil
	} else {
		if typ == typeAlert {
			nl := -1
			for i := 0; i < len(texts); i++ {
				if texts[i] == '\n' {
					nl = i
					break
				}
			}
			rest := texts[nl+1:]
			prefix := "<p>"
			texts = prefix + rest
		}

		var sourceRef []byte
		if nn := n.FirstChild(); nn != nil {
			segs := nn.Lines()
			total := segs.Len()
			var start, stop int
			capturedLines := 0
			for i := 0; i < total; i++ {
				if capturedLines >= 2 {
					break
				}
				line := segs.At(i)
				if capturedLines == 0 {
					start = line.Start
				}
				stop = line.Stop
				capturedLines++
			}
			span := stop - start
			sourceRef = make([]byte, 0, span)
			idx := start
			for idx < stop {
				sourceRef = append(sourceRef, src[idx])
				idx++
			}
		}

		pageInner := docCtx.Document
		page := docCtx.Document
		filename := docCtx.Filename
		pid := ctx.PeekPid()
		if pid > 0 {
			lookup := docCtx.DocumentLookup
			if lookup != nil {
				if v := lookup(pid); v != nil {
					pageInner = v
				}
			}
		}
		if pageInner == nil {
			pageInner = page
		}

		astAttrs := n.Attributes()
		safeAttrs := astAttrs
		attrMap := make(map[string]any)
		converted := make([]attributes.Attribute, 0, len(astAttrs))
		if len(astAttrs) > 0 {
			filtered := make([]ast.Attribute, 0, len(astAttrs))
			for _, v := range astAttrs {
				nameBytes := v.Name
				nameLower := strings.ToLower(string(nameBytes))
				if strings.HasPrefix(nameLower, "on") {
					continue
				}
				nv := v
				var vv any
				switch vvv := v.Value.(type) {
				case bool:
					vv = vvv
				case float64:
					vv = vvv
				case []any:
					hlRanges := make([][2]int, 0, len(vvv))
					cleaned := make([]any, 0, len(vvv))
					for _, l := range vvv {
						if ln, ok := l.(float64); ok {
							startLine := int(ln) - 1
							endLine := startLine
							hlRanges = append(hlRanges, [2]int{startLine, endLine})
							cleaned = append(cleaned, ln)
						} else if rng, ok := l.([]uint8); ok {
							rangeText := string([]byte(rng))
							parts := strings.Split(rangeText, "-")
							lhs, err := strconv.Atoi(parts[0])
							if err != nil {
								continue
							}
							rhs := lhs
							if len(parts) > 1 {
								parsed, perr := strconv.Atoi(parts[1])
								if perr != nil {
									continue
								}
								rhs = parsed
							}
							left := lhs - 1
							right := rhs - 1
							hlRanges = append(hlRanges, [2]int{left, right})
							cleaned = append(cleaned, rng)
						}
					}
					vv = hlRanges
					nv.Value = cleaned
				case []byte:
					copied := make([]byte, len(vvv))
					copy(copied, vvv)
					vv = string(copied)
				default:
					panic(fmt.Sprintf("not implemented: %T", vvv))
				}
				converted = append(converted, attributes.Attribute{Name: nameLower, Value: vv})
				filtered = append(filtered, nv)
			}
			safeAttrs = filtered
			for _, item := range converted {
				attrMap[item.Name] = item.Value
			}
		}

		bqctx := &blockquoteContext{
			page:             page,
			pageInner:        pageInner,
			typ:              typ,
			alertType:        alertType,
			text:             hstring.RenderedString(texts),
			sourceRef:        sourceRef,
			ordinal:          ordinal,
			attrMap:          attrMap,
			AttributesHolder: attributes.New(safeAttrs, attributes.AttributesOwnerGeneral),
		}

		bqctx.createPos = func() htext.Position {
			if resolver, ok := renderer.(hooks.ElementPositionResolver); ok {
				return resolver.ResolvePosition(bqctx)
			}
			lineNumber := 1
			columnNumber := 1
			return htext.Position{
				Filename:     filename,
				LineNumber:   lineNumber,
				ColumnNumber: columnNumber,
			}
		}

		cr := renderer.(hooks.BlockquoteRenderer)
		hookCtx := renderCtx.Ctx
		err := cr.RenderBlockquote(
			hookCtx,
			w,
			bqctx,
		)
		if err != nil {
			return ast.WalkContinue, herrors.NewFileErrorFromPos(err, bqctx.createPos())
		}

		return ast.WalkContinue, nil
	}
}

type blockquoteContext struct {
	page      any
	pageInner any
	text      hstring.RenderedString
	typ       string
	sourceRef []byte
	alertType string
	ordinal   int
	attrMap   map[string]any

	// This is only used in error situations and is expensive to create,
	// so delay creation until needed.
	pos       htext.Position
	posInit   sync.Once
	createPos func() htext.Position

	*attributes.AttributesHolder
}

func (c *blockquoteContext) Type() string {
	return c.typ
}

func (c *blockquoteContext) AlertType() string {
	return c.alertType
}

func (c *blockquoteContext) Page() any {
	return c.page
}

func (c *blockquoteContext) PageInner() any {
	return c.pageInner
}

func (c *blockquoteContext) Text() hstring.RenderedString {
	return c.text
}

func (c *blockquoteContext) Ordinal() int {
	return c.ordinal
}

func (c *blockquoteContext) Attributes() map[string]any {
	if c.attrMap != nil {
		return c.attrMap
	}
	if c.AttributesHolder != nil {
		return c.AttributesHolder.Attributes()
	}
	return map[string]any{}
}

func (c *blockquoteContext) Position() htext.Position {
	c.posInit.Do(func() {
		c.pos = c.createPos()
	})
	return c.pos
}

func (c *blockquoteContext) PositionerSourceTarget() []byte {
	return c.sourceRef
}

var _ hooks.PositionerSourceTargetProvider = (*blockquoteContext)(nil)

// https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax#alerts
// Five types:
// [!NOTE], [!TIP], [!WARNING], [!IMPORTANT], [!CAUTION]
var gitHubAlertRe = regexp.MustCompile(`^<p>\[!(NOTE|TIP|WARNING|IMPORTANT|CAUTION)\]`)

// resolveGitHubAlert returns one of note, tip, warning, important or caution.
// An empty string if no match.
func resolveGitHubAlert(s string) string {
	m := gitHubAlertRe.FindStringSubmatch(s)
	if len(m) == 2 {
		return strings.ToLower(m[1])
	}
	return ""
}

